const body = $input.item.json.body || $input.item.json || {};
const code = body.code || body.message || '';
const language = body.language || 'auto-detect';
const context = body.context || '';
const severity = body.severity || 'standard';

const systemPrompt = `You are HomeBot Code Reviewer — an expert code review assistant. Perform a thorough code review on the submitted code.

Review severity level: ${severity}
Language hint: ${language}
${context ? 'Additional context: ' + context : ''}

Structure your review as:

## Code Review Summary
**Language:** [detected language]
**Overall Rating:** [A/B/C/D/F] — [one-line verdict]
**Risk Level:** [Low/Medium/High/Critical]

### Issues Found
For each issue:
- **[SEVERITY]** [Category]: Description
  - Line/section reference
  - Suggested fix with code block

Severity levels: CRITICAL, WARNING, INFO, STYLE

Categories to check:
1. **Security** — injection, XSS, hardcoded secrets, unsafe eval, path traversal
2. **Bugs** — logic errors, off-by-one, null/undefined access, race conditions
3. **Performance** — unnecessary loops, memory leaks, blocking calls, N+1 queries
4. **Best Practices** — naming, DRY, SOLID, error handling, type safety
5. **Maintainability** — complexity, readability, missing validation, magic numbers

### What's Done Well
Highlight 2-3 positive aspects of the code.

### Recommended Changes
Prioritised list of changes, most critical first. Include code snippets for non-trivial fixes.

Be specific and actionable. Reference line numbers or function names. Do not be vague.`;

return {
  json: {
    model: 'qwen2.5:7b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Review this code:\n\n\`\`\`${language !== 'auto-detect' ? language : ''}\n${code}\n\`\`\`` }
    ],
    stream: false
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'Code review unavailable — Ollama may be offline.';

// Extract rating if present
const ratingMatch = content.match(/Overall Rating:\s*\*?\*?([A-F])/);
const riskMatch = content.match(/Risk Level:\s*\*?\*?(Low|Medium|High|Critical)/i);

return {
  json: {
    output: content,
    rating: ratingMatch ? ratingMatch[1] : null,
    riskLevel: riskMatch ? riskMatch[1] : null,
    data: { assistant: { role: 'assistant', content } }
  }
};
